  // ---------------------------------------------------------------------------
  // Audio: a fully rendered synthwave track keeps timing rock solid on phones
  // ---------------------------------------------------------------------------

  let audioCtx = null;
  let masterGain = null;
  let musicGain = null;
  let songBuffer = null;
  let musicSource = null;
  let sfxBuffers = {};
