  async function prepareSong() {
    if (songBuffer) return;
    if (preparingPromise) return preparingPromise;
    preparingPromise = (async () => {
      if (!audioCtx) throw new Error('AudioContext unavailable');
      const sampleRate = Math.min(48000, audioCtx.sampleRate || 44100);
      const length = Math.ceil((SONG_DURATION + 2) * sampleRate);
      const offline = new OfflineAudioContext(2, length, sampleRate);
      buildTrack(offline);
      songBuffer = await offline.startRendering();
    })().finally(() => {
      preparingPromise = null;
    });
    return preparingPromise;
  }

  async function ensureAudio() {
    const AudioCtor = window.AudioContext || window.webkitAudioContext;
    if (!AudioCtor) return false;
    try {
      if (!audioCtx) {
        audioCtx = new AudioCtor({ latencyHint: 'interactive' });
        masterGain = audioCtx.createGain();
        masterGain.gain.value = muted ? 0 : 0.9;
        masterGain.connect(audioCtx.destination);
        musicGain = audioCtx.createGain();
        musicGain.gain.value = 0.86;
        musicGain.connect(masterGain);
        sfxBuffers = makeSfx(audioCtx);
      }
      if (audioCtx.state !== 'running') await audioCtx.resume();
      return true;
    } catch (error) {
      console.warn('Audio unavailable, running silently.', error);
      return false;
    }
  }

  function setMuted(next) {
    muted = next;
    try { localStorage.setItem(STORAGE_MUTE, muted ? '1' : '0'); } catch (_) { /* ignore */ }
    if (masterGain && audioCtx) {
