Start flow:
```
async function startRun(){
 if(state==='loading') return;
 state='loading';
 ui.playBtn.classList.add('loading'); ui.playLabel.textContent='SYNCING';
 stopMusic(false);
 ui.resultScreen.classList.add('hidden');
 ui.pauseScreen.classList.add('hidden');
 ui.countdown.classList.add('hidden');
 const token=++runId;
 const ok=await ensureAudio();
 if(ok){ useAudio=true; try{await prepareSong();}catch(e){useAudio=false; console.warn}}
 if(token!==runId){...}
 if(useAudio && songBuffer){...} else useAudio=false;
 resetRun();
 state='playing';
 ui.title.classList.add('hidden');
 ui.hud.classList.remove('hidden');
