      ctx.globalCompositeOperation = 'lighter';
      ctx.fillStyle = `rgba(255,45,84,${0.2 + (1 - alpha) * 0.45})`;
      ctx.beginPath();
      ctx.ellipse(0, 0, size * 0.46, size * 0.46, 0, 0, TAU);
      ctx.fill();
    }
    ctx.restore();
    ctx.restore();

