      ctx.save();
      ctx.globalCompositeOperation = 'lighter';
      ctx.strokeStyle = `rgba(255,45,84,${(1 - (time - enemy.missedAt) / 0.5) * 0.34})`;
      ctx.lineWidth = 1.4;
