        const offset = (i - 1) * size * 0.1;
        ctx.beginPath();
        ctx.moveTo(x - size * 0.44, y + offset);
        ctx.lineTo(x + size * 0.44, y + offset + (i % 2 ? 4 : -4));
        ctx.stroke();
      }
      ctx.restore();
    }
  }

