    const start = Math.round(time * sampleRate);
    const samples = Math.floor(0.9 * sampleRate);
    for (let i = 0; i < samples; i++) {
      const u = i / sampleRate;
      const n = (start + i) & (noiseLength - 1);
      const high = noise[n] - noise[(n - 1) & (noiseLength - 1)];
