    }
  };

  const chords = [
    { root: 110.0, notes: [220.0, 261.63, 329.63] },
    { root: 87.31, notes: [174.61, 220.0, 261.63] },
    { root: 130.81, notes: [261.63, 329.63, 392.0] },
    { root: 98.0, notes: [196.0, 246.94, 293.66] },
  ];
  const bassPattern = [0, 0, 12, 0, 7, 0, 10, 7];

