      const volume = (chorus ? 1.22 : 1) * (outro ? 0.7 : 1);
      pluck(barStart + i * step, note * octave, step * 2.15, volume, pan);
      pluck(barStart + i * step + BEAT * 0.75, note * octave, step * 1.4, volume * 0.22, -pan);
    }

