function buildReticleSprite(color) {
  const reticle = document.createElement('canvas');
  reticle.width = 512;
  reticle.height = 512;
  const g = reticle.getContext('2d');
  g.translate(256, 256);
  g.lineJoin = 'round';
  g.lineCap = 'round';

  g.strokeStyle = rgba(color, 0.92);
  g.shadowColor = color;
  g.shadowBlur = 18;
  g.lineWidth = 4;
  g.beginPath();
  g.arc(0, 0, 200, 0, TAU);
  g.stroke();

  g.shadowBlur = 0;
  g.strokeStyle = rgba(color, 0.42);
  g.lineWidth = 1.8;
  g.beginPath();
  g.arc(0, 0, 136, 0, TAU);
  g.stroke();

  g.strokeStyle = rgba(color, 0.66);
  g.lineWidth = 2.4;
  for (let i = 0; i < 12; i++) {
    const angle = (i / 12) * TAU;
    const inner = i % 3 === 0 ? 184 : 191;
    g.beginPath();
    g.moveTo(Math.cos(angle) * inner, Math.sin(angle) * inner);
    g.lineTo(Math.cos(angle) * 211, Math.sin(angle) * 211);
    g.stroke();
  }

  g.strokeStyle = rgba(color, 0.72);
  g.lineWidth = 2.6;
  const bracket = 180;
  const tick = 30;
  for (const sx of [-1, 1]) {
    for (const sy of [-1, 1]) {
      const x = sx * bracket;
      const y = sy * bracket;
      g.beginPath();
      g.moveTo(x, y);
      g.lineTo(x - sx * tick, y);
      g.moveTo(x, y);
      g.lineTo(x, y - sy * tick);
      g.stroke();
    }
  }

  return reticle;
}

function buildRingSprite() {
  const ring = document.createElement('canvas');
  ring.width = 512;
  ring.height = 512;
