function drawReticle(now) {
  const time = Math.max(0, getSongTime());
  const beatPos = time / BEAT;
  const beatFraction = beatPos - Math.floor(beatPos);
  const beatPulse = Math.exp(-beatFraction * 7);
  const targetInfo = nearestVisualTarget();
  nearestTarget = targetInfo;
  const color = targetInfo ? TYPES[targetInfo.enemy.type].rgb : '71,247,255';
  const approach = targetInfo ? targetInfo.approach : 0;
  const R = strikeR * (1 + beatPulse * 0.04);
  const close = targetInfo && Math.abs(targetInfo.delta) <= HIT_WINDOW.good;

  ctx.save();
  ctx.globalCompositeOperation = 'lighter';

  ctx.strokeStyle = `rgba(${color},${0.2 + approach * 0.42})`;
  ctx.lineWidth = 1.2 + approach * 1.3;
  ctx.beginPath();
  ctx.ellipse(cx, strikeY, R, R * 0.32, 0, 0, TAU);
  ctx.stroke();

  ctx.strokeStyle = `rgba(${color},${0.12 + approach * 0.24})`;
  ctx.lineWidth = 1;
  ctx.beginPath();
  ctx.ellipse(cx, strikeY, R * 0.68, R * 0.22, 0, 0, TAU);
  ctx.stroke();

  ctx.strokeStyle = `rgba(${color},${0.22 + approach * 0.45})`;
  ctx.lineWidth = 1.3;
  for (let i = 0; i < 12; i++) {
    const angle = (i / 12) * TAU + now * 0.16;
    const inner = R * (i % 3 === 0 ? 0.91 : 0.95);
    const outer = R * 1.045;
    ctx.beginPath();
    ctx.moveTo(cx + Math.cos(angle) * inner, strikeY + Math.sin(angle) * inner * 0.32);
    ctx.lineTo(cx + Math.cos(angle) * outer, strikeY + Math.sin(angle) * outer * 0.32);
    ctx.stroke();
  }

  const bracket = R * 0.9;
  const tick = R * 0.14;
  ctx.strokeStyle = `rgba(${color},${0.2 + approach * 0.52})`;
  ctx.lineWidth = 1.6;
  for (const sx of [-1, 1]) {
    for (const sy of [-1, 1]) {
      const x = cx + sx * bracket;
      const y = strikeY + sy * bracket * 0.32;
      ctx.beginPath();
      ctx.moveTo(x, y);
      ctx.lineTo(x - sx * tick, y);
      ctx.moveTo(x, y);
      ctx.lineTo(x, y - sy * tick * 0.32);
      ctx.stroke();
    }
  }

  const timingR = R * (1 + (1 - approach) * 1.45);
  ctx.strokeStyle = close ? `rgba(255,255,255,${0.55 + (1 - Math.abs(targetInfo.delta) / HIT_WINDOW.good) * 0.4})` : `rgba(${color},${0.1 + approach * 0.48})`;
  ctx.lineWidth = 1.4 + approach * 2.2;
  ctx.beginPath();
  ctx.ellipse(cx, strikeY, timingR, timingR * 0.32, 0, 0, TAU);
